'use strict';
const KEY='elevor360d-marketplace-v1';const FAV_KEY='elevor360d-marketplace-favorites-v7';const ENQUIRY_KEY='elevor360d-marketplace-enquiries-v8';const OFFER_KEY='elevor360d-marketplace-offers-v9';const SALES_KEY='elevor360d-marketplace-sales-v10';let sales={};try{const s=JSON.parse(localStorage.getItem(SALES_KEY)||'{}');if(s&&typeof s==='object'&&!Array.isArray(s))sales=s}catch{}let offers=[];try{const o=JSON.parse(localStorage.getItem(OFFER_KEY)||'[]');if(Array.isArray(o))offers=o.filter(x=>x&&typeof x.id==='string'&&typeof x.message==='string').slice(0,200)}catch{}let enquiries=[];try{const e=JSON.parse(localStorage.getItem(ENQUIRY_KEY)||'[]');if(Array.isArray(e))enquiries=e.filter(x=>x&&typeof x.message==='string').slice(0,200)}catch{};let favorites=[];try{const f=JSON.parse(localStorage.getItem(FAV_KEY)||'[]');if(Array.isArray(f))favorites=[...new Set(f.filter(x=>typeof x==='string'))]}catch{}
let listings=[];let editingId=null;let photoDraft=[];const $=id=>document.getElementById(id);const cats=['Electronics','Home & Garden','Clothing','Sports & Outdoors','Vehicles & Parts','Books & Media','Collectables','Baby & Kids','Pets & Supplies','Tools & DIY','Furniture','Other'];
try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(raw))listings=raw.filter(valid)}catch{}
function valid(x){return x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.price==='number'&&Number.isFinite(x.price)&&x.price>=0&&typeof x.type==='string'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(listings));return true}catch{alert('Device storage is full or unavailable. Export a backup, then remove old listings or large photos.');return false}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function show(page){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==page);document.querySelectorAll('nav button').forEach(b=>{if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});render();window.scrollTo(0,0)}
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>show(b.dataset.page)));
function startEdit(x){editingId=x.id;$('name').value=x.name;$('price').value=x.price;$('type').value=x.type;$('condition').value=x.condition||'Used - Good';$('location').value=x.location||'';$('description').value=x.description||'';$('sellerEmail').value=x.sellerEmail||'';$('sellerPhone').value=x.sellerPhone||'';$('photo').value='';photoDraft=[...(Array.isArray(x.photos)?x.photos:(x.photo?[x.photo]:[]))];renderPhotoPreview();$('formHeading').textContent='Edit listing';$('saveListing').textContent='Save Changes';$('cancelEdit').hidden=false;$('editHint').hidden=false;$('notice').textContent='Editing '+x.name;show('sell')}
function cancelEdit(){editingId=null;photoDraft=[];renderPhotoPreview();$('listingForm').reset();$('formHeading').textContent='List an item';$('saveListing').textContent='Save Listing';$('cancelEdit').hidden=true;$('editHint').hidden=true}
$('cancelEdit').addEventListener('click',()=>{cancelEdit();$('notice').textContent='Editing cancelled.';show('mine')});
function photosFor(x){const ok=p=>typeof p==='string'&&(p.startsWith('data:image/')||(x.cloud===true&&/^https:\/\//.test(p)));return Array.isArray(x.photos)?x.photos.filter(ok):(ok(x.photo)?[x.photo]:[])}
function renderPhotoPreview(){const wrap=$('photoPreview');if(!wrap)return;wrap.replaceChildren();photoDraft.forEach((src,i)=>{const thumb=el('div','thumb');const im=el('img');im.src=src;im.alt='Photo '+(i+1);const remove=el('button','','×');remove.type='button';remove.setAttribute('aria-label','Remove photo '+(i+1));remove.addEventListener('click',()=>{photoDraft.splice(i,1);renderPhotoPreview()});thumb.append(im,remove);wrap.append(thumb)});const msg=el('span','muted',photoDraft.length+'/4 photos selected');wrap.append(msg)}
$('clearPhotos').addEventListener('click',()=>{photoDraft=[];$('photo').value='';renderPhotoPreview()});
$('photo').addEventListener('change',async e=>{const files=[...e.target.files];if(files.length+photoDraft.length>4){alert('Maximum four photos per listing.');e.target.value='';return}try{for(const f of files)photoDraft.push(await resizePhoto(f));renderPhotoPreview()}catch(err){alert(err.message)}finally{e.target.value=''}});
function card(x,manage){const article=el('article','item');const photos=photosFor(x);if(photos.length){const img=el('img','main-photo');img.src=photos[0];img.alt=x.name;article.append(img);if(photos.length>1){const gal=el('div','gallery');photos.forEach((src,i)=>{const thumb=el('img');thumb.src=src;thumb.alt='View photo '+(i+1);thumb.tabIndex=0;thumb.addEventListener('click',()=>img.src=src);thumb.addEventListener('keydown',e=>{if(e.key==='Enter')img.src=src});gal.append(thumb)});article.append(gal)}}else{const ph=el('div','empty','📦 No photo');ph.style.height='160px';article.append(ph)}const d=el('div','details');d.append(el('strong','',x.name),el('div','price','£'+x.price.toFixed(2)),el('p','muted',[x.type,x.condition,x.location].filter(Boolean).join(' · ')));if(x.description)d.append(el('p','',x.description));if(x.status==='sold')d.append(el('span','sold-tag','SOLD'));const view=el('button','secondary','View Details');view.type='button';view.addEventListener('click',()=>openDetail(x.id));d.append(view,favoriteButton(x));if(manage){const actions=el('div','item-actions');const duplicate=el('button','secondary','Duplicate');duplicate.addEventListener('click',()=>{cancelEdit();editingId=null;$('name').value=x.name+' (copy)';$('price').value=x.price;$('type').value=x.type;$('condition').value=x.condition||'Used - Good';$('location').value=x.location||'';$('description').value=x.description||'';$('sellerEmail').value=x.sellerEmail||'';$('sellerPhone').value=x.sellerPhone||'';photoDraft=[...photosFor(x)];renderPhotoPreview();$('notice').textContent='Review the copied item and save it as a new listing.';show('sell')});const edit=el('button','secondary','Edit');edit.addEventListener('click',()=>startEdit(x));const status=el('button','secondary',x.status==='sold'?'Mark Available':'Mark Sold');status.addEventListener('click',()=>{const old=x.status;x.status=x.status==='sold'?'available':'sold';if(!save())x.status=old;render()});const del=el('button','secondary','Delete');del.addEventListener('click',()=>{if(confirm('Permanently delete this listing?')){const old=listings;listings=listings.filter(i=>i.id!==x.id);if(!save())listings=old;render()}});actions.append(edit,duplicate,status,del);d.append(actions)}article.append(d);return article}
function toggleFavorite(id){const previous=[...favorites];favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem(FAV_KEY,JSON.stringify(favorites))}catch{favorites=previous;alert("Unable to save favourites on this device.")}render()}
function favoriteButton(x){const saved=favorites.includes(x.id),b=el("button","favorite-btn",saved?"♥ Saved":"♡ Save Item");b.type="button";b.setAttribute("aria-pressed",String(saved));b.setAttribute("aria-label",saved?"Remove "+x.name+" from saved items":"Save "+x.name+" to favourites");b.addEventListener("click",()=>toggleFavorite(x.id));return b}
function renderFavorites(){const saved=[...listings,...cloudListings].filter(x=>favorites.includes(x.id));$("favoriteCount").textContent="("+saved.length+")";$("favoriteResults").replaceChildren(...(saved.length?saved.map(x=>card(x,false)):[el("div","empty","No saved items yet. Browse listings and tap ♡ Save Item.")]));}
$("clearFavorites").addEventListener("click",()=>{if(!favorites.length)return;if(confirm("Remove all saved items from favourites?")){favorites=[];try{localStorage.setItem(FAV_KEY,"[]")}catch{}render()}});
function render(){const q=$('search').value.toLowerCase().trim(),cat=$('category').value,condition=$('filterCondition').value,town=$('filterTown').value.toLowerCase().trim(),minRaw=$('minPrice').value,maxRaw=$('maxPrice').value,min=minRaw===''?null:Number(minRaw),max=maxRaw===''?null:Number(maxRaw),photoOnly=$('photosOnly').checked;const found=listings.filter(x=>x.status!=='sold'&&(!cat||x.type===cat)&&(!q||[x.name,x.description,x.location,x.type].join(' ').toLowerCase().includes(q))&&(!condition||x.condition===condition)&&(!town||(x.location||'').toLowerCase().includes(town))&&(min===null||x.price>=min)&&(max===null||x.price<=max)&&(!photoOnly||photosFor(x).length>0));const sort=$('sortBy').value;found.sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:sort==='az'?a.name.localeCompare(b.name):sort==='oldest'?(Date.parse(a.created)||0)-(Date.parse(b.created)||0):(Date.parse(b.created)||0)-(Date.parse(a.created)||0));$('resultCount').textContent=found.length+' '+(found.length===1?'listing':'listings')+' found';$('results').replaceChildren(...(found.length?found.map(x=>card(x,false)):[el('div','empty','No matching listings. Try clearing the filters or add an item.')]));renderMine();renderFavorites();renderSales();renderCloud();}
function renderMine(){const available=listings.filter(x=>x.status!=='sold');$('statAll').textContent=listings.length;$('statAvailable').textContent=available.length;$('statSold').textContent=listings.length-available.length;$('statValue').textContent=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(available.reduce((sum,x)=>sum+x.price,0));const q=$('manageSearch').value.trim().toLowerCase(),status=$('manageStatus').value,sort=$('manageSort').value;const mine=listings.filter(x=>(status==='all'||(status==='sold'?x.status==='sold':x.status!=='sold'))&&(!q||[x.name,x.description,x.location,x.type].join(' ').toLowerCase().includes(q)));mine.sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:sort==='oldest'?(Date.parse(a.created)||0)-(Date.parse(b.created)||0):(Date.parse(b.created)||0)-(Date.parse(a.created)||0));$('myResults').replaceChildren(...(mine.length?mine.map(x=>card(x,true)):[el('div','empty',listings.length?'No listings match these dashboard filters.':'You have no listings yet.')]));}
['manageSearch'].forEach(id=>$(id).addEventListener('input',renderMine));['manageStatus','manageSort'].forEach(id=>$(id).addEventListener('change',renderMine));$('newListing').addEventListener('click',()=>{cancelEdit();show('sell')});
$('search').addEventListener('input',render);$('category').addEventListener('change',render);['minPrice','maxPrice','filterTown'].forEach(id=>$(id).addEventListener('input',render));['filterCondition','sortBy','photosOnly'].forEach(id=>$(id).addEventListener('change',render));$('clearFilters').addEventListener('click',()=>{['search','category','minPrice','maxPrice','filterCondition','filterTown'].forEach(id=>$(id).value='');$('sortBy').value='newest';$('photosOnly').checked=false;render()});
function resizePhoto(file){return new Promise((resolve,reject)=>{if(!file){resolve('');return}if(!file.type.startsWith('image/')){reject(new Error('Choose an image file.'));return}if(file.size>15*1024*1024){reject(new Error('Choose a photo smaller than 15 MB.'));return}const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{const scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.7))}catch(e){reject(e)}finally{URL.revokeObjectURL(url)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Unable to read image.'))};img.src=url})}
$('listingForm').addEventListener('submit',async e=>{e.preventDefault();const price=Number($('price').value);if(!Number.isFinite(price)||price<0||price>100000000){alert('Enter a valid price.');return}const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{const existing=editingId?listings.find(x=>x.id===editingId):null;if(editingId&&!existing)throw Error('Listing no longer exists.');const photos=[...photoDraft];const photo=photos[0]||'';const x={id:existing?.id||(crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random()),name:$('name').value.trim(),price,type:$('type').value,condition:$('condition').value,location:$('location').value.trim(),description:$('description').value.trim(),sellerEmail:$('sellerEmail').value.trim(),sellerPhone:$('sellerPhone').value.trim(),photo,photos,created:existing?.created||new Date().toISOString(),status:existing?.status||'available',updated:new Date().toISOString()};if(x.sellerPhone&&!/^[+0-9 ()-]{7,30}$/.test(x.sellerPhone))throw Error('Enter a valid telephone number or leave it blank.');if(x.sellerEmail&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.sellerEmail))throw Error('Enter a valid contact email or leave it blank.');if(!x.name||!cats.includes(x.type))throw Error('Enter an item title and category.');const old=listings;listings=existing?listings.map(i=>i.id===existing.id?x:i):[x,...listings];if(!save()){listings=old;return}const edited=!!existing;cancelEdit();$('notice').textContent=edited?'Listing updated successfully.':'Listing saved on this device.';show('mine')}catch(err){alert(err.message||'Could not save listing.')}finally{btn.disabled=false}});
$('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({app:'Elevor360D Marketplace Pro',version:18,listings,favorites,enquiries,offers,sales,paymentArrangements:JSON.parse(localStorage.getItem("elevor360d-payment-notes-v18")||"[]")},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='marketplace-v18-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('importButton').addEventListener('click',()=>$('import').click());$('import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('Backup is too large.');const data=JSON.parse(await f.text());if(data.app!=='Elevor360D Marketplace Pro'||!Array.isArray(data.listings)||!data.listings.every(valid))throw Error('Invalid marketplace backup.');if(confirm('Replace all current listings with '+data.listings.length+' backup listings?')){const old=listings;listings=data.listings;if(!save()){listings=old}else{const oldFav=[...favorites];favorites=Array.isArray(data.favorites)?[...new Set(data.favorites.filter(id=>typeof id==='string'&&listings.some(x=>x.id===id)))]:[];try{localStorage.setItem(FAV_KEY,JSON.stringify(favorites))}catch{favorites=oldFav};if(Array.isArray(data.enquiries)){enquiries=data.enquiries.filter(x=>x&&typeof x.message==='string').slice(0,200);try{localStorage.setItem(ENQUIRY_KEY,JSON.stringify(enquiries))}catch{}}if(Array.isArray(data.offers)){offers=data.offers.filter(x=>x&&typeof x.id==='string'&&typeof x.message==='string').slice(0,200);try{localStorage.setItem(OFFER_KEY,JSON.stringify(offers))}catch{}}if(data.sales&&typeof data.sales==='object'&&!Array.isArray(data.sales)){sales=data.sales;try{localStorage.setItem(SALES_KEY,JSON.stringify(sales))}catch{}}if(Array.isArray(data.paymentArrangements)){try{localStorage.setItem('elevor360d-payment-notes-v18',JSON.stringify(data.paymentArrangements.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string').slice(0,200)))}catch{}}if(typeof window.renderPaymentArrangements==='function')window.renderPaymentArrangements();renderOffers();$('notice').textContent='Backup restored.' }render()}}catch(err){alert(err.message)}finally{e.target.value=''}});

function openDetail(id){const x=listings.find(y=>y.id===id)||cloudListings.find(y=>y.id===id);if(!x)return;const dlg=$('itemDialog'),body=$('detailBody');$('detailTitle').textContent=x.name;body.replaceChildren();const pics=photosFor(x);if(pics.length){const hero=el('img','detail-hero');hero.src=pics[0];hero.alt=x.name+' photo 1';body.append(hero);if(pics.length>1){const thumbs=el('div','detail-thumbs');pics.forEach((src,i)=>{const b=el('button');b.type='button';b.setAttribute('aria-label','View photo '+(i+1));b.setAttribute('aria-pressed',String(i===0));const thumb=el('img');thumb.src=src;thumb.alt='Photo '+(i+1);b.append(thumb);b.addEventListener('click',()=>{hero.src=src;hero.alt=x.name+' photo '+(i+1);thumbs.querySelectorAll('button').forEach((btn,j)=>btn.setAttribute('aria-pressed',String(j===i)))});thumbs.append(b)});body.append(thumbs)}}else body.append(el('div','empty','📦 No photograph supplied'));body.append(el('div','price','£'+x.price.toFixed(2)),el('p','muted',[x.type,x.condition,x.location].filter(Boolean).join(' · ')));if(x.status==='sold')body.append(el('span','sold-tag','SOLD'));body.append(el('h3','','Description'),el('p','detail-description',x.description||'No description provided.'));const actions=el('div','detail-actions');actions.append(favoriteButton(x));if(x.status!=='sold'){
const message='Hello, I am interested in your listing: '+x.name+' (£'+x.price.toFixed(2)+'). Is it still available?';
const label=el('label','','Your enquiry message');const editor=el('textarea');editor.value=message;editor.maxLength=1200;editor.setAttribute('aria-label','Buyer enquiry message');body.append(label,editor);
const remember=()=>{const record={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),listingId:x.id,title:x.name,message:editor.value.trim(),created:new Date().toISOString()};if(!record.message){alert('Please enter an enquiry message.');return false}enquiries.unshift(record);enquiries=enquiries.slice(0,200);try{localStorage.setItem(ENQUIRY_KEY,JSON.stringify(enquiries));renderEnquiries()}catch{enquiries.shift();alert('Unable to save enquiry log. You can still use the contact options.')}return true};
const makeOffer=el('button','','Make an Offer');makeOffer.type='button';makeOffer.addEventListener('click',()=>openOffer(x));actions.append(makeOffer);const copy=el('button','secondary','Copy Enquiry');copy.type='button';copy.addEventListener('click',async()=>{if(!remember())return;try{await navigator.clipboard.writeText(editor.value);$('notice').textContent='Enquiry copied and logged locally.'}catch{window.prompt('Copy this enquiry:',editor.value)}});actions.append(copy);
if(x.sellerEmail){const contact=el('button','','Email Seller');contact.type='button';contact.addEventListener('click',()=>{if(!remember())return;window.location.href='mailto:'+encodeURIComponent(x.sellerEmail)+'?subject='+encodeURIComponent('Enquiry about '+x.name)+'&body='+encodeURIComponent(editor.value)});actions.append(contact)}
if(x.sellerPhone){const clean=x.sellerPhone.replace(/[^+0-9]/g,'');const links=el('div','contact-links');const call=el('a','','Call Seller');call.href='tel:'+clean;call.addEventListener('click',()=>remember());links.append(call);let digits=clean.replace(/\D/g,'');if(digits.startsWith('0'))digits='44'+digits.slice(1);if(digits.length>=9&&digits.length<=15){const wa=el('a','','WhatsApp Seller');wa.href='https://wa.me/'+digits+'?text='+encodeURIComponent(editor.value);wa.target='_blank';wa.rel='noopener noreferrer';wa.addEventListener('click',()=>remember());links.append(wa)}actions.append(links)}
if(x.cloud){const msg=el('button','','Message Seller in App');msg.type='button';msg.addEventListener('click',()=>{dlg.close();startMessageForListing(x.id.slice(6))});actions.append(msg)}
if(!x.sellerEmail&&!x.sellerPhone&&!x.cloud)actions.append(el('p','muted','No seller contact details supplied. You can copy your enquiry, but the app cannot deliver it.'));
}body.append(actions);if(!dlg.open)dlg.showModal()}
$('closeDetail').addEventListener('click',()=>$('itemDialog').close());$('itemDialog').addEventListener('click',e=>{if(e.target===$('itemDialog'))$('itemDialog').close()});

function renderEnquiries(){const wrap=$('enquiryResults');wrap.replaceChildren();if(!enquiries.length){wrap.append(el('p','muted','No enquiries recorded yet.'));return}enquiries.forEach(x=>{const a=el('article','enquiry-entry');a.append(el('strong','',x.title||'Listing'),el('p','muted',new Date(x.created).toLocaleString('en-GB')),el('p','',x.message));const copy=el('button','secondary','Copy Message');copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(x.message);$('notice').textContent='Message copied.'}catch{window.prompt('Copy message:',x.message)}});const del=el('button','secondary','Delete Entry');del.addEventListener('click',()=>{enquiries=enquiries.filter(e=>e.id!==x.id);try{localStorage.setItem(ENQUIRY_KEY,JSON.stringify(enquiries))}catch{}renderEnquiries()});a.append(copy,' ',del);wrap.append(a)})}
$('clearEnquiries').addEventListener('click',()=>{if(confirm('Delete the entire local enquiry log?')){enquiries=[];try{localStorage.setItem(ENQUIRY_KEY,'[]')}catch{}renderEnquiries()}});
renderEnquiries();
function persistOffers(){try{localStorage.setItem(OFFER_KEY,JSON.stringify(offers));renderOffers();return true}catch{alert('Unable to save offers. Export a backup or free device storage.');return false}}
function openOffer(x){if(x.status==='sold'){alert('This item is marked sold.');return}const dlg=$('itemDialog'),body=$('detailBody');$('detailTitle').textContent='Make an offer — '+x.name;body.replaceChildren();const p=el('p','muted','Asking price: £'+x.price.toFixed(2));const priceLabel=el('label','','Your offer (£)');const price=el('input');price.type='number';price.min='0.01';price.max='100000000';price.step='0.01';price.value=x.price.toFixed(2);const nameLabel=el('label','','Your name (optional)');const name=el('input');name.maxLength=80;const messageLabel=el('label','','Message to seller');const message=el('textarea');message.maxLength=1200;const refresh=()=>{message.value='Hello, I would like to offer £'+Number(price.value||0).toFixed(2)+' for your '+x.name+'. Would you consider this offer?'};refresh();price.addEventListener('input',refresh);const note=el('p','muted','Saving an offer does not send it. You can copy it or open your email app after saving.');const actions=el('div','detail-actions');const saveButton=el('button','','Save Offer');saveButton.type='button';saveButton.addEventListener('click',()=>{const amount=Number(price.value);if(!Number.isFinite(amount)||amount<=0||amount>100000000){alert('Enter a valid offer greater than £0.');return}const msg=message.value.trim();if(!msg){alert('Enter an offer message.');return}const offer={id:crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random(),listingId:x.id,title:x.name,askingPrice:x.price,amount:Number(amount.toFixed(2)),buyerName:name.value.trim(),sellerEmail:x.sellerEmail||'',sellerPhone:x.sellerPhone||'',message:msg,status:'draft',created:new Date().toISOString()};offers.unshift(offer);offers=offers.slice(0,200);if(!persistOffers()){offers=offers.filter(o=>o.id!==offer.id);return}dlg.close();show('offers');$('notice').textContent='Offer saved locally. Open My Offers to copy or send it.'});const back=el('button','secondary','Back to Item');back.type='button';back.addEventListener('click',()=>openDetail(x.id));actions.append(saveButton,back);body.append(p,priceLabel,price,nameLabel,name,messageLabel,message,note,actions);if(!dlg.open)dlg.showModal()}
function renderOffers(){const wrap=$('offerResults');$('offerCount').textContent='('+offers.length+')';wrap.replaceChildren();if(!offers.length){wrap.append(el('div','empty','No offers saved yet. Open an available listing and choose Make an Offer.'));return}offers.forEach(o=>{const entry=el('article','offer-entry');entry.append(el('strong','',o.title||'Listing'),el('div','price','£'+Number(o.amount||0).toFixed(2)),el('p','muted','Asking price: £'+Number(o.askingPrice||0).toFixed(2)+' · '+(new Date(o.created).toLocaleString('en-GB'))));entry.append(el('p','',o.message));const label=el('label','','Offer status (manually updated)');const select=el('select');[['draft','Draft'],['sent','Sent externally'],['accepted','Accepted (manual)'],['declined','Declined (manual)'],['withdrawn','Withdrawn']].forEach(([v,t])=>{const opt=el('option','',t);opt.value=v;select.append(opt)});select.value=['draft','sent','accepted','declined','withdrawn'].includes(o.status)?o.status:'draft';select.addEventListener('change',()=>{const old=o.status;o.status=select.value;if(!persistOffers()){o.status=old;select.value=old}});entry.append(label,select);const buttons=el('div','toolbar');const copy=el('button','secondary','Copy Offer');copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(o.message);$('notice').textContent='Offer copied.'}catch{window.prompt('Copy this offer:',o.message)}});buttons.append(copy);if(o.sellerEmail){const email=el('a','contact-links','Email Offer');email.href='mailto:'+encodeURIComponent(o.sellerEmail)+'?subject='+encodeURIComponent('Offer for '+o.title)+'&body='+encodeURIComponent(o.message);email.style.cssText='display:inline-block;padding:11px;border-radius:9px;background:#e5eaf2;color:#17243a;text-decoration:none';email.addEventListener('click',()=>{const old=o.status;o.status='sent';if(!persistOffers())o.status=old});buttons.append(email)}if(o.sellerPhone){let digits=o.sellerPhone.replace(/\D/g,'');if(digits.startsWith('0'))digits='44'+digits.slice(1);if(digits.length>=9&&digits.length<=15){const wa=el('a','','WhatsApp Offer');wa.href='https://wa.me/'+digits+'?text='+encodeURIComponent(o.message);wa.target='_blank';wa.rel='noopener noreferrer';wa.style.cssText='display:inline-block;padding:11px;border-radius:9px;background:#e5eaf2;color:#17243a;text-decoration:none';wa.addEventListener('click',()=>{const old=o.status;o.status='sent';if(!persistOffers())o.status=old});buttons.append(wa)}}const del=el('button','secondary','Delete');del.addEventListener('click',()=>{if(!confirm('Delete this saved offer?'))return;const prev=[...offers];offers=offers.filter(x=>x.id!==o.id);if(!persistOffers())offers=prev});buttons.append(del);entry.append(buttons);wrap.append(entry)})}
$('clearOffers').addEventListener('click',()=>{if(!offers.length||!confirm('Delete all locally saved offers?'))return;const prev=[...offers];offers=[];if(!persistOffers())offers=prev});renderOffers();

function persistSales(){try{localStorage.setItem(SALES_KEY,JSON.stringify(sales));renderSales();return true}catch{alert('Unable to save sales records. Export a backup and free storage.');return false}}
function renderSales(){const sold=listings.filter(x=>x.status==='sold');$('salesCount').textContent=sold.length;const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n);$('salesTotal').textContent=money(sold.reduce((sum,x)=>sum+(Number.isFinite(Number(sales[x.id]?.amount))?Number(sales[x.id].amount):x.price),0));const wrap=$('salesResults');wrap.replaceChildren();if(!sold.length){wrap.append(el('div','empty','No items marked sold. Use My Listings → Mark Sold to add a sales record.'));return}sold.forEach(x=>{const record=sales[x.id]||{};const article=el('article','enquiry-entry');article.append(el('strong','',x.name),el('p','muted','Original asking price: '+money(x.price)));const dateLabel=el('label','','Date sold');const date=el('input');date.type='date';date.value=record.date||'';const amountLabel=el('label','','Agreed sale price (£)');const amount=el('input');amount.type='number';amount.min='0';amount.max='100000000';amount.step='0.01';amount.value=record.amount??x.price;const notesLabel=el('label','','Private sale notes (optional)');const notes=el('textarea');notes.maxLength=1000;notes.value=record.notes||'';const btn=el('button','','Save Sale Details');btn.type='button';btn.addEventListener('click',()=>{const n=Number(amount.value);if(!amount.value.trim()||!Number.isFinite(n)||n<0||n>100000000){alert('Enter a valid sale price.');return}const prev=sales[x.id];sales[x.id]={date:date.value,amount:Number(n.toFixed(2)),notes:notes.value.trim()};if(!persistSales()){if(prev)sales[x.id]=prev;else delete sales[x.id]}else $('notice').textContent='Sale details saved.'});article.append(dateLabel,date,amountLabel,amount,notesLabel,notes,btn);wrap.append(article)})}
$('exportSales').addEventListener('click',()=>{const sold=listings.filter(x=>x.status==='sold');const esc=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[['Item','Category','Asking price','Agreed price','Date sold','Notes'],...sold.map(x=>[x.name,x.type,x.price,sales[x.id]?.amount??x.price,sales[x.id]?.date||'',sales[x.id]?.notes||''])];const csv='\uFEFF'+rows.map(r=>r.map(esc).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='marketplace-sales-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});


// V11 public read-only Supabase REST integration. No remote writes until authenticated RLS in V12.
const CLOUD_SETTINGS='elevor360d-marketplace-cloud-v11';
let cloudListings=[];
// Public settings are distributed with the app, not requested from visitors.
// Existing owner browser settings are a migration fallback until config file is completed.
let cloudConfig={url:'',key:''};
const publicConfig=window.MARKETPLACE_PUBLIC_CONFIG||{};
const hasPublicConfig=typeof publicConfig.url==='string'&&/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(publicConfig.url.trim())&&typeof publicConfig.key==='string'&&/^(sb_publishable_[A-Za-z0-9_-]+|eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)$/.test(publicConfig.key.trim());
if(hasPublicConfig)cloudConfig={url:publicConfig.url.trim().replace(/\/$/,''),key:publicConfig.key.trim()};
else try{const v=JSON.parse(localStorage.getItem(CLOUD_SETTINGS)||'{}');if(v&&typeof v.url==='string'&&typeof v.key==='string')cloudConfig=v}catch{}
$('cloudUrl').value=cloudConfig.url;$('cloudKey').value=cloudConfig.key;
if(hasPublicConfig){$('cloudSave').hidden=true;$('cloudDisconnect').hidden=true;$('cloudUrl').closest('.owner-settings').hidden=true;}

function cloudMessage(msg){$('cloudStatus').textContent=msg}
function renderCloud(){const target=$('cloudResults');if(!target)return;target.replaceChildren();if(!cloudListings.length){target.append(el('div','empty','No published cloud listings yet.'));return}for(const x of cloudListings){const item=card(x,false);if(x.ownerId){const b=el('button','secondary','View Seller & Ratings');b.type='button';b.addEventListener('click',()=>openSeller(x.ownerId));const actions=item.querySelector('.item-actions')||item;actions.append(b)}target.append(item)}}
function validateCloudConfig(url,key){const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Enter your HTTPS Supabase project URL without a path.');if(!/^(sb_publishable_[A-Za-z0-9_-]+|eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)$/.test(key))throw Error('Use a publishable key or legacy anon JWT. Never use a secret or service-role key.');return u.origin}
$('cloudSave').addEventListener('click',()=>{try{const url=validateCloudConfig($('cloudUrl').value.trim().replace(/\/$/,'' )+'/', $('cloudKey').value.trim());cloudConfig={url,key:$('cloudKey').value.trim()};localStorage.setItem(CLOUD_SETTINGS,JSON.stringify(cloudConfig));cloudMessage('Connection saved. Select Refresh Listings to test.')}catch(e){cloudMessage(e.message)}});
$('cloudDisconnect').addEventListener('click',()=>{cloudConfig={url:'',key:''};cloudListings=[];localStorage.removeItem(CLOUD_SETTINGS);$('cloudUrl').value='';$('cloudKey').value='';cloudMessage('Disconnected. Local listings are unaffected.');render()});
async function refreshCloud(){if(!cloudConfig.url||!cloudConfig.key){cloudMessage('Marketplace owner: configure marketplace-config.js once, then upload it to GitHub Pages.');return}cloudMessage('Loading published listings…');try{validateCloudConfig(cloudConfig.url+'/',cloudConfig.key);const ctl=new AbortController();const timeout=setTimeout(()=>ctl.abort(),12000);let res;try{res=await fetch(cloudConfig.url+'/rest/v1/marketplace_listings?select=id,title,price,category,condition,location,description,photos,created_at,status,owner_id&status=eq.published&order=created_at.desc&limit=100',{headers:{apikey:cloudConfig.key,...(cloudConfig.key.startsWith('eyJ')?{Authorization:'Bearer '+cloudConfig.key}:{})},signal:ctl.signal,cache:'no-store'})}finally{clearTimeout(timeout)}if(!res.ok)throw Error('HTTP '+res.status+' — check SQL setup, RLS policy and project URL/key.');const data=await res.json();if(!Array.isArray(data))throw Error('Unexpected response from Supabase');cloudListings=data.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&Number.isFinite(Number(x.price))).map(x=>({id:'cloud:'+x.id,name:x.title,price:Number(x.price),type:x.category||'Other',condition:x.condition||'',location:x.location||'',description:x.description||'',photos:Array.isArray(x.photos)?x.photos.filter(p=>typeof p==='string'&&p.startsWith('https://')).slice(0,4):[],status:'available',created:x.created_at,cloud:true,ownerId:x.owner_id}));cloudMessage('Connected · '+cloudListings.length+' published listing(s) loaded · '+cloudListings.filter(x=>x.photos.length).length+' with photo links.');render()}catch(e){cloudMessage('Unable to load: '+(e.name==='AbortError'?'request timed out':e.message)+'. Existing local listings are unaffected.')}}
$('cloudRefresh').addEventListener('click',refreshCloud);

let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('install').style.display='inline-block'});$('install').addEventListener('click',async()=>{if(!deferred)return;deferred.prompt();await deferred.userChoice;deferred=null;$('install').style.display='none'});window.addEventListener('appinstalled',()=>{$('install').style.display='none';deferred=null});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));render();

// V12 Supabase Auth: password never persisted. Tokens are session-scoped to this browser tab.
const AUTH_SESSION_KEY='elevor360d-marketplace-auth-v12';
let authSession=null;
try{const t=JSON.parse(sessionStorage.getItem(AUTH_SESSION_KEY)||'null');if(t&&typeof t.access_token==='string'&&typeof t.refresh_token==='string')authSession=t}catch{}
function authStatus(t){$('authStatus').textContent=t}
function authView(){const signed=!!(authSession&&authSession.user);$('authGuest').hidden=signed;$('authMember').hidden=!signed;$('authIdentity').textContent=signed?(authSession.user.email||'Account'):'';if(!signed)$('authDisplayName').value=''}
function saveAuthSession(t){authSession=t;if(t)sessionStorage.setItem(AUTH_SESSION_KEY,JSON.stringify(t));else sessionStorage.removeItem(AUTH_SESSION_KEY);authView()}
function authConfig(){if(!cloudConfig.url||!cloudConfig.key)throw Error('Marketplace connection not configured. The owner must set marketplace-config.js.');validateCloudConfig(cloudConfig.url+'/',cloudConfig.key);return cloudConfig}
async function authFetch(path,method,body,token){const c=authConfig();const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),15000);try{const res=await fetch(c.url+path,{method,headers:{apikey:c.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body===undefined?undefined:JSON.stringify(body),signal:ctl.signal,cache:'no-store'});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Error(data.msg||data.error_description||data.message||data.error||('Request failed (HTTP '+res.status+')'));return data}finally{clearTimeout(timer)}}
async function ensureAuth(){if(!authSession)throw Error('Sign in first.');if(Date.now()<Number(authSession.expires_at||0)*1000-60000)return authSession;const d=await authFetch('/auth/v1/token?grant_type=refresh_token','POST',{refresh_token:authSession.refresh_token});if(!d.access_token)throw Error('Session expired. Please sign in again.');saveAuthSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in});return authSession}
async function loadProfile(){const a=await ensureAuth();const data=await authFetch('/rest/v1/marketplace_profiles?select=display_name&id=eq.'+encodeURIComponent(a.user.id),'GET',undefined,a.access_token);if(Array.isArray(data)&&data[0])$('authDisplayName').value=data[0].display_name||''}
async function authAction(fn){try{authStatus('Please wait…');await fn()}catch(e){authStatus('Error: '+(e.name==='AbortError'?'request timed out':e.message))}}
$('authSignUp').addEventListener('click',()=>authAction(async()=>{const email=$('authEmail').value.trim(),password=$('authPassword').value;if(!email||password.length<8)throw Error('Enter an email and a password of at least 8 characters.');const d=await authFetch('/auth/v1/signup','POST',{email,password});if(d.access_token&&d.refresh_token){saveAuthSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in});authStatus('Account created and signed in.');await loadProfile()}else authStatus('If registration was accepted, check your email for a confirmation link, then sign in.')}));
$('authLogin').addEventListener('click',()=>authAction(async()=>{const email=$('authEmail').value.trim(),password=$('authPassword').value;const d=await authFetch('/auth/v1/token?grant_type=password','POST',{email,password});if(!d.access_token||!d.user)throw Error('No session returned. Confirm your email if required.');saveAuthSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in});$('authPassword').value='';authStatus('Signed in securely.');await loadProfile()}));
$('authReset').addEventListener('click',()=>authAction(async()=>{const email=$('authEmail').value.trim();if(!email)throw Error('Enter your email address.');await authFetch('/auth/v1/recover','POST',{email});authStatus('If the account exists, Supabase will send password reset instructions.')}));
$('authSaveProfile').addEventListener('click',()=>authAction(async()=>{const a=await ensureAuth(),name=$('authDisplayName').value.trim();if(name.length<2||name.length>60)throw Error('Display name must be 2–60 characters.');const c=authConfig();const res=await fetch(c.url+'/rest/v1/marketplace_profiles',{method:'POST',headers:{apikey:c.key,Authorization:'Bearer '+a.access_token,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id:a.user.id,display_name:name})});if(!res.ok)throw Error('Profile save failed (HTTP '+res.status+'). Run V12 SQL setup.');authStatus('Seller display name saved.')}));
$('authLogout').addEventListener('click',()=>authAction(async()=>{if(authSession){try{await authFetch('/auth/v1/logout','POST',{},authSession.access_token)}catch{}}saveAuthSession(null);authStatus('Signed out. Local listings remain on this device.')}));
authView();if(authSession)authAction(async()=>{await loadProfile();authStatus('Signed in securely.')});


// V13: authenticated cloud publishing. Local listings remain separate and untouched.
const onlineStatus=t=>{$('onlineStatus').textContent=t};
async function cloudRequest(method,path,body){const c=authConfig(),s=await ensureAuth();const res=await fetch(c.url+'/rest/v1/'+path,{method,headers:{apikey:c.key,Authorization:'Bearer '+s.access_token,'Content-Type':'application/json',Prefer:'return=representation'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});let payload;try{payload=await res.json()}catch{payload=null}if(!res.ok)throw Error((payload&&payload.message)||('Supabase HTTP '+res.status+'. Check V13 SQL policies.'));return payload}
function cloudPayload(){const title=$('onlineTitle').value.trim(),price=Number($('onlinePrice').value),raw=$('onlinePhoto').value.trim();if(title.length<1||title.length>90)throw Error('Enter a product title (1–90 characters).');if(!$('onlinePrice').value.trim()||!Number.isFinite(price)||price<0||price>99999999)throw Error('Enter a valid price.');let photos=[];if(raw){const u=new URL(raw);if(u.protocol!=='https:'||u.username||u.password)throw Error('Photo link must use HTTPS.');photos=[u.href]}return {title,price,category:$('onlineCategory').value,condition:$('onlineCondition').value,location:$('onlineLocation').value.trim().slice(0,80),description:$('onlineDescription').value.trim().slice(0,1500),photos}}
// V25.2: device photo uploads use Supabase Storage; never expose service-role keys.
let onlinePreviewURL=null;
let preparedOnlinePhoto=null;
let onlinePhotoProcessing=null;
const onlineFile=$('onlinePhotoFile');
const MB=1024*1024;
function photoSize(bytes){return (bytes/MB).toFixed(2)+' MB'}
function resetOnlinePhoto(){onlineFile.value='';preparedOnlinePhoto=null;onlinePhotoProcessing=null;if(onlinePreviewURL)URL.revokeObjectURL(onlinePreviewURL);onlinePreviewURL=null;$('onlinePhotoPreview').hidden=true;$('onlinePhotoPreview').removeAttribute('src');$('onlinePhotoStatus').textContent='';}
function compressOnlinePhoto(file){return new Promise((resolve,reject)=>{
 if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))return reject(Error('Choose a JPG, PNG, WebP or GIF photograph.'));
 if(file.size>25*MB)return reject(Error('Photo exceeds 25 MB. Please choose a smaller photo.'));
 const objectURL=URL.createObjectURL(file),img=new Image();
 img.onerror=()=>{URL.revokeObjectURL(objectURL);reject(Error('This image could not be opened. Try a JPG or PNG.'))};
 img.onload=async()=>{URL.revokeObjectURL(objectURL);try{
  if(!img.naturalWidth||!img.naturalHeight)throw Error('The image is empty.');
  const maxEdge=1600,scale=Math.min(1,maxEdge/Math.max(img.naturalWidth,img.naturalHeight));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
  const ctx=canvas.getContext('2d');if(!ctx)throw Error('Photo resizing is unavailable on this device.');
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
  const toBlob=(quality)=>new Promise((ok,no)=>canvas.toBlob(b=>b?ok(b):no(Error('Could not compress the photo.')),'image/jpeg',quality));
  let blob=await toBlob(.82);
  for(const q of [.7,.55,.4]){if(blob.size<=5*MB)break;blob=await toBlob(q)}
  if(blob.size>5*MB)throw Error('This image could not be reduced below 5 MB. Please choose a smaller image.');
  resolve({blob,originalSize:file.size,width:canvas.width,height:canvas.height});
 }catch(e){reject(e)}};
 img.src=objectURL;
})}
onlineFile.addEventListener('change',()=>{
 if(onlinePreviewURL)URL.revokeObjectURL(onlinePreviewURL);onlinePreviewURL=null;preparedOnlinePhoto=null;
 const f=onlineFile.files?.[0];if(!f){resetOnlinePhoto();return}
 if(!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)||f.size>25*MB){resetOnlinePhoto();$('onlinePhotoStatus').textContent='Choose a JPG, PNG, WebP or GIF image up to 25 MB.';return}
 onlinePreviewURL=URL.createObjectURL(f);$('onlinePhotoPreview').src=onlinePreviewURL;$('onlinePhotoPreview').hidden=false;
 $('onlinePhotoStatus').textContent='Preparing photo ('+photoSize(f.size)+')…';
 const currentFile=f;
 onlinePhotoProcessing=compressOnlinePhoto(f).then(result=>{
  if(onlineFile.files?.[0]!==currentFile)return;
  preparedOnlinePhoto=result.blob;
  $('onlinePhotoStatus').textContent='Ready to upload: '+photoSize(result.blob.size)+' (original '+photoSize(result.originalSize)+', '+result.width+'×'+result.height+' pixels).';
 }).catch(err=>{if(onlineFile.files?.[0]===currentFile){preparedOnlinePhoto=null;$('onlinePhotoStatus').textContent='Photo error: '+err.message;}});
});
$('onlinePhotoClear').addEventListener('click',resetOnlinePhoto);
async function uploadOnlinePhoto(s){
 const f=onlineFile.files?.[0];if(!f)return null;
 if(onlinePhotoProcessing)await onlinePhotoProcessing;
 if(!preparedOnlinePhoto)throw Error('Photo could not be prepared. Select another photo and try again.');
 const blob=preparedOnlinePhoto;
 if(blob.size>5*MB)throw Error('Prepared photo exceeds 5 MB.');
 const path=s.user.id+'/'+crypto.randomUUID()+'.jpg';const c=authConfig();onlineStatus('Uploading optimised product photo ('+photoSize(blob.size)+')…');
 const r=await fetch(c.url+'/storage/v1/object/marketplace-photos/'+path,{method:'POST',headers:{apikey:c.key,Authorization:'Bearer '+s.access_token,'Content-Type':'image/jpeg','x-upsert':'false'},body:blob});
 if(!r.ok){let d={};try{d=await r.json()}catch{}throw Error('Photo upload failed: '+(d.message||d.error||'HTTP '+r.status)+'. Check Supabase Storage setup.');}
 return c.url+'/storage/v1/object/public/marketplace-photos/'+path;
}
async function publishOnline(status){
 const btn=$('onlinePublish'),draft=$('onlineDraft');btn.disabled=draft.disabled=true;
 try{
  const selected=onlineFile.files?.[0];
  if(!selected && !$('onlinePhoto').value.trim())throw Error('Please choose a product photo before publishing.');
  onlineStatus('Checking account…');const session=await ensureAuth();
  const payload={...cloudPayload(),owner_id:session.user.id,status};
  const photo=await uploadOnlinePhoto(session);if(photo)payload.photos=[photo];
  if(!payload.photos.length)throw Error('No photo was attached. Please select the photo again.');
  onlineStatus('Saving listing and photo address…');
  const created=await cloudRequest('POST','marketplace_listings',payload);
  if(!Array.isArray(created)||!created[0]?.id)throw Error('Supabase did not return the new listing. Check database permissions.');
  const saved=created[0];
  if(!Array.isArray(saved.photos)||saved.photos[0]!==payload.photos[0]){
   onlineStatus('Listing saved, but the photo address was not returned by Supabase. Please check the marketplace_listings.photos column and SQL policies.');
   return;
  }
  let publiclyAccessible=true;
  try{const probe=await fetch(payload.photos[0],{method:'GET',cache:'no-store'});publiclyAccessible=probe.ok;if(probe.body)await probe.body.cancel()}catch{publiclyAccessible=false}
  if(!publiclyAccessible){onlineStatus('Listing saved, but the photo is not publicly accessible. Check that Supabase Storage bucket marketplace-photos is PUBLIC and the image exists.');return}
  resetOnlinePhoto();await Promise.all([refreshCloud(),refreshMineCloud()]);
  const visible=cloudListings.find(x=>x.id==='cloud:'+saved.id);
  if(status==='published'&&(!visible||!visible.photos?.length))onlineStatus('Listing saved but its photo did not appear in the public feed. Refresh Listings and check the photos field in Supabase.');
  else onlineStatus(status==='published'?'Product and photo published successfully.':'Private cloud draft and photo saved.');
 }catch(e){onlineStatus('Error: '+e.message)}finally{btn.disabled=draft.disabled=false}
}
$('onlinePublish').addEventListener('click',()=>publishOnline('published'));
$('onlineDraft').addEventListener('click',()=>publishOnline('draft'));
async function refreshMineCloud(){const target=$('onlineMineResults');target.replaceChildren();try{const a=await ensureAuth();const rows=await cloudRequest('GET','marketplace_listings?select=id,title,price,status,created_at&owner_id=eq.'+encodeURIComponent(a.user.id)+'&order=created_at.desc&limit=100');if(!Array.isArray(rows))throw Error('Unexpected response');if(!rows.length){target.append(el('p','muted','No cloud listings in your account yet.'));return}for(const item of rows){const wrap=el('article','enquiry-entry');wrap.append(el('strong','',item.title),el('p','muted','£'+Number(item.price).toFixed(2)+' · '+item.status));const action=el('div','toolbar');for(const [state,label] of [['published','Publish'],['draft','Unpublish'],['sold','Mark Sold']]){if(item.status===state)continue;const b=el('button','secondary',label);b.addEventListener('click',async()=>{try{onlineStatus('Updating listing…');await cloudRequest('PATCH','marketplace_listings?id=eq.'+encodeURIComponent(item.id),{status:state});onlineStatus('Listing updated.');await Promise.all([refreshMineCloud(),refreshCloud()])}catch(e){onlineStatus('Error: '+e.message)}});action.append(b)}const del=el('button','secondary','Delete Cloud Listing');del.addEventListener('click',async()=>{if(!confirm('Permanently delete this cloud listing? This cannot be undone.'))return;try{const deleted=await cloudRequest('DELETE','marketplace_listings?id=eq.'+encodeURIComponent(item.id)+'&owner_id=eq.'+encodeURIComponent(a.user.id));if(!Array.isArray(deleted)||deleted.length!==1||deleted[0].id!==item.id)throw Error('Supabase did not delete this listing. Run SUPABASE_V25_6_DELETE_FIX.sql, then try again.');onlineStatus('Cloud listing deleted successfully.');await Promise.all([refreshMineCloud(),refreshCloud()])}catch(e){onlineStatus('Error: '+e.message)}});action.append(del);wrap.append(action);target.append(wrap)}}catch(e){target.append(el('p','muted','Sign in to view your cloud listings. '+e.message))}}
$('onlineMineRefresh').addEventListener('click',refreshMineCloud);

// Load public products for every visitor without requiring login or manual connection.
if(cloudConfig.url&&cloudConfig.key)refreshCloud();


// V14 private buyer/seller messaging; database RLS enforces participation and listing ownership.
let messageRows=[];let selectedThread=null;let activeRecipient=null;
const messagesStatus=t=>{$('messagesStatus').textContent=t};
async function messageRequest(method,path,body){return cloudRequest(method,path,body)}
async function startMessageForListing(id){try{const a=await ensureAuth();const c=authConfig();const r=await fetch(c.url+'/rest/v1/marketplace_listings?select=id,title,owner_id,status&id=eq.'+encodeURIComponent(id),{headers:{apikey:c.key,Authorization:'Bearer '+a.access_token}});if(!r.ok)throw Error('Unable to check listing');const data=await r.json();if(!data.length||data[0].status!=='published')throw Error('Listing unavailable');if(data[0].owner_id===a.user.id)throw Error('This is your own listing.');selectedThread=id;activeRecipient=data[0].owner_id;show('messages');await refreshMessages();messagesStatus('Select the listing below and write your enquiry.');}catch(e){alert('Sign in under My Account to message a seller. '+e.message);show('account')}}
async function sendMessage(listingId,content,recipient){const body=content.trim();if(!body||body.length>2000)throw Error('Message must be 1–2000 characters.');await messageRequest('POST','marketplace_messages',{listing_id:listingId,body,recipient_id:recipient});await refreshMessages()}
async function refreshMessages(){const target=$('messageThreads');target.replaceChildren();try{const a=await ensureAuth();messagesStatus('Loading messages…');const rows=await messageRequest('GET','marketplace_messages?select=id,listing_id,sender_id,recipient_id,body,created_at&order=created_at.asc&limit=500');messageRows=Array.isArray(rows)?rows:[];const mine=await messageRequest('GET','marketplace_listings?select=id,title,owner_id,status&owner_id=eq.'+encodeURIComponent(a.user.id)+'&limit=200');const other=await messageRequest('GET','marketplace_listings?select=id,title,owner_id,status&status=eq.published&limit=200');const listingsMap=new Map([...other,...mine].map(x=>[x.id,x]));const groups=new Map();for(const m of messageRows){const otherUser=m.sender_id===a.user.id?m.recipient_id:m.sender_id;const key=m.listing_id+'|'+otherUser;if(!groups.has(key))groups.set(key,{listingId:m.listing_id,otherUser,messages:[]});groups.get(key).messages.push(m)}if(selectedThread&&!Array.from(groups.values()).some(g=>g.listingId===selectedThread)){const item=listingsMap.get(selectedThread);if(item&&item.owner_id!==a.user.id)groups.set(selectedThread+'|'+item.owner_id,{listingId:selectedThread,otherUser:item.owner_id,messages:[]})}for(const g of groups.values()){const listing=listingsMap.get(g.listingId);const panel=el('article','message-thread');panel.append(el('strong','',listing?.title||'Listing '+g.listingId.slice(0,8)),el('p','muted',g.messages.length+' message(s)'));for(const m of g.messages){const bubble=el('div','message-bubble'+(m.sender_id===a.user.id?' mine':''));bubble.append(el('strong','',m.sender_id===a.user.id?'You':'Other participant'),el('p','muted',new Date(m.created_at).toLocaleString('en-GB')),el('div','',m.body));panel.append(bubble)}const input=el('textarea');input.maxLength=2000;input.placeholder='Write a private message…';input.setAttribute('aria-label','Message about '+(listing?.title||'listing'));const send=el('button','','Send Message');send.type='button';send.addEventListener('click',async()=>{send.disabled=true;try{await sendMessage(g.listingId,input.value,g.otherUser);messagesStatus('Message sent.')}catch(e){messagesStatus('Unable to send: '+e.message)}finally{send.disabled=false}});panel.append(input,send);target.append(panel)}if(!groups.size)target.append(el('p','muted','No conversations yet. Open a published cloud product and select Message Seller in App.'));messagesStatus('Messages loaded. Only conversation participants can read them.');$('messageCount').textContent=messageRows.length?'('+messageRows.length+')':'';}catch(e){messagesStatus('Sign in or check connection: '+e.message)}}
$('messagesRefresh').addEventListener('click',refreshMessages);

// V15: Public seller reputation and contact-based buyer reviews.
let activeSellerId='';
function sellerStatus(t){$('sellerStatus').textContent=t}
function validSellerId(id){return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)}
async function publicSellerRequest(path){const c=authConfig();const r=await fetch(c.url+'/rest/v1/'+path,{headers:{apikey:c.key,...(c.key.startsWith('eyJ')?{Authorization:'Bearer '+c.key}:{})},cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message||'Request failed '+r.status);return d}
async function openSeller(id){if(!validSellerId(id)){sellerStatus('Invalid seller ID');return}activeSellerId=id;$('sellerLookup').value=id;document.querySelector('button[data-page="sellers"]').click();await refreshSeller()}
async function refreshSeller(){const id=activeSellerId;if(!validSellerId(id)){sellerStatus('Choose a seller from a cloud listing first.');return}sellerStatus('Loading seller profile…');$('sellerSummary').replaceChildren();$('sellerReviews').replaceChildren();$('sellerReviewForm').hidden=true;try{const data=await publicSellerRequest('rpc/marketplace_public_seller_profile?p_seller_id='+encodeURIComponent(id));if(!data||!data.seller_id){sellerStatus('Seller not found.');return}const summary=$('sellerSummary');summary.append(el('h3','',data.display_name||'Marketplace seller'),el('p','muted','Average rating: '+(data.review_count?Number(data.average_rating).toFixed(1)+' / 5 from '+data.review_count+' review(s)':'No reviews yet')+' · '+data.published_count+' published listing(s)'));const reviews=await publicSellerRequest('marketplace_seller_reviews?select=rating,comment,created_at&seller_id=eq.'+encodeURIComponent(id)+'&order=created_at.desc&limit=50');$('sellerReviews').append(el('h3','','Recent reviews'));for(const r of reviews){const entry=el('article','enquiry-entry');entry.append(el('strong','', '★'.repeat(r.rating)+'☆'.repeat(5-r.rating)),el('p','muted',new Date(r.created_at).toLocaleDateString('en-GB')),el('p','',r.comment||'No written comment'));$('sellerReviews').append(entry)}if(!reviews.length)$('sellerReviews').append(el('p','muted','No reviews yet.'));$('sellerReviewForm').hidden=!authSession||authSession.user?.id===id;sellerStatus('Seller profile loaded.')}catch(e){sellerStatus('Unable to load profile: '+e.message+' (check V15 SQL setup).')}}
$('sellerRefresh').addEventListener('click',refreshSeller);
$('sellerReviewSubmit').addEventListener('click',async()=>{if(!validSellerId(activeSellerId))return;const btn=$('sellerReviewSubmit');btn.disabled=true;try{const rating=Number($('sellerStars').value),comment=$('sellerComment').value.trim();if(!Number.isInteger(rating)||rating<1||rating>5||comment.length>500)throw Error('Invalid review');await cloudRequest('POST','marketplace_seller_reviews',{seller_id:activeSellerId,rating,comment});$('sellerComment').value='';sellerStatus('Review submitted.');await refreshSeller()}catch(e){sellerStatus('Review not saved: '+e.message)}finally{btn.disabled=false}});

// V16: privileged admin RPCs. The browser never decides permissions; Supabase checks auth.uid().
let adminReady=false;
async function adminRPC(name,body){return cloudRequest('POST','rpc/'+name,body||{});}
async function adminCheck(){const nav=$('adminNav');try{if(!authSession){nav.hidden=true;document.getElementById('sellerManagementNav').hidden=true;adminReady=false;return}const result=await adminRPC('marketplace_is_admin');adminReady=result===true;nav.hidden=!adminReady;document.getElementById('sellerManagementNav').hidden=!adminReady;if(!adminReady&&$('admin')&&!$('admin').hidden)show('account')}catch(e){adminReady=false;nav.hidden=true;document.getElementById('sellerManagementNav').hidden=true;}}
async function adminRefresh(){const status=$('adminStatus'),target=$('adminListings');status.textContent='Loading admin dashboard…';target.replaceChildren();try{if(!adminReady)throw Error('This account is not authorised as an administrator.');const result=await adminRPC('marketplace_admin_dashboard');if(!result||!result.stats||!Array.isArray(result.listings))throw Error('Unexpected response from Supabase.');const st=result.stats;for(const [id,key] of [['adminUsers','profiles'],['adminPublished','published'],['adminDrafts','drafts'],['adminSold','sold'],['adminReviews','reviews']])$(id).textContent=Number(st[key]||0).toLocaleString('en-GB');for(const x of result.listings){const item=el('article','enquiry-entry');item.append(el('strong','',x.title),el('p','muted','£'+Number(x.price).toFixed(2)+' · '+x.status+' · '+new Date(x.created_at).toLocaleDateString('en-GB')));if(x.status==='published'){const b=el('button','secondary','Unpublish');b.addEventListener('click',async()=>{if(!confirm('Unpublish this listing? It will no longer be visible to buyers.'))return;b.disabled=true;try{await adminRPC('marketplace_admin_unpublish',{p_listing_id:x.id});status.textContent='Listing unpublished.';await adminRefresh();await refreshCloud()}catch(e){status.textContent='Unable to unpublish: '+e.message;b.disabled=false}});item.append(b)}target.append(item)}if(!result.listings.length)target.append(el('p','muted','No listings found.'));status.textContent='Dashboard updated.'}catch(e){status.textContent='Admin dashboard unavailable: '+e.message}}
$('adminRefresh').addEventListener('click',adminRefresh);
document.querySelector('button[data-page="admin"]').addEventListener('click',()=>{if(adminReady)adminRefresh()});
// Recheck on every account change and when returning to the app.
const oldAuthView=authView;authView=function(){oldAuthView();adminCheck()};
adminCheck();


// V17: authenticated reporting and administrator moderation.
function reportNotice(t){$('myReportsStatus').textContent=t}
async function submitListingReport(x){
 if(!authSession){alert('Please sign in under My Account to report a listing.');show('account');return}
 if(x.ownerId===authSession.user?.id){alert('You cannot report your own listing.');return}
 const reason=prompt('Why are you reporting this listing? Enter one: Scam, Prohibited item, Misleading, Harassment, Other');
 if(reason===null)return;
 const valid=['Scam','Prohibited item','Misleading','Harassment','Other'];
 const matched=valid.find(v=>v.toLowerCase()===reason.trim().toLowerCase());
 if(!matched){alert('Please enter one of the listed reasons.');return}
 const details=prompt('Optional details for the administrator (maximum 1000 characters):','');
 if(details===null)return;
 if(details.length>1000){alert('Details are too long.');return}
 try{await cloudRequest('POST','marketplace_listing_reports',{listing_id:x.id.slice(6),reason:matched,details:details.trim()});alert('Report submitted confidentially. Thank you.')}catch(e){alert('Unable to submit report: '+e.message)}
}
// Add a report control to cloud cards after the existing card has been built.
const renderCloudV16=renderCloud;
renderCloud=function(){renderCloudV16();const cards=$('cloudResults').querySelectorAll('.item');cloudListings.forEach((x,i)=>{if(!cards[i])return;const b=el('button','secondary','Report Listing');b.type='button';b.addEventListener('click',()=>submitListingReport(x));(cards[i].querySelector('.item-actions')||cards[i]).append(b)})};
$('myReportsRefresh').addEventListener('click',async()=>{const target=$('myReportsList');target.replaceChildren();try{const a=await ensureAuth();const rows=await cloudRequest('GET','marketplace_listing_reports?select=id,reason,details,status,created_at&reporter_id=eq.'+encodeURIComponent(a.user.id)+'&order=created_at.desc&limit=100');for(const r of rows){const entry=el('article','enquiry-entry');entry.append(el('strong','',r.reason),el('p','muted',new Date(r.created_at).toLocaleString('en-GB')+' · '+r.status),el('p','',r.details||'No additional details'));target.append(entry)}if(!rows.length)target.append(el('p','muted','You have not submitted any reports.'));reportNotice('Your reports loaded.')}catch(e){reportNotice('Unable to load reports: '+e.message)}});
async function moderationRefresh(){const target=$('moderationQueue');target.replaceChildren();if(!adminReady)return;try{const rows=await adminRPC('marketplace_admin_reports');for(const r of rows){const entry=el('article','enquiry-entry');entry.append(el('strong','',r.listing_title||'Listing unavailable'),el('p','muted',r.reason+' · '+r.status+' · '+new Date(r.created_at).toLocaleString('en-GB')),el('p','',r.details||'No details'));const actions=el('div','toolbar');for(const [action,label] of [['reviewing','Mark Reviewing'],['dismissed','Dismiss Report'],['blocked','Block Listing'],['resolved','Resolve Report'],['restore','Restore Listing']]){if(action==='restore'&&r.listing_status!=='blocked')continue;if(action==='blocked'&&r.listing_status==='blocked')continue;const b=el('button','secondary',label);b.type='button';b.addEventListener('click',async()=>{if(['blocked','restore'].includes(action)&&!confirm(label+'?'))return;b.disabled=true;try{await adminRPC('marketplace_admin_moderate',{p_report_id:r.id,p_action:action});await moderationRefresh();await refreshCloud();}catch(e){alert('Moderation failed: '+e.message);b.disabled=false}});actions.append(b)}entry.append(actions);target.append(entry)}if(!rows.length)target.append(el('p','muted','No reports received.'))}catch(e){target.append(el('p','muted','Unable to load reports: '+e.message))}}
const adminRefreshV16=adminRefresh;
adminRefresh=async function(){await adminRefreshV16();await moderationRefresh()};
